"""Sortie V1, batch 3: Chebyshev's upper bound ppi ( z ) <_ ( log 4 + eps ) z / log z eventually (Lean: eventually_primePi_le), from pnt."""
import sys, os; sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..')); from tm import *
sys.path.insert(0, os.path.dirname(__file__)); from v1_lib import *
only = sys.argv[1:]
def run(w):
    if only and w.label not in only: return True
    return w.run()

RAT = lambda A: '( ( ppi ` %s ) / ( %s / ( log ` %s ) ) )' % (A, A, A)
ABS = lambda A: '( abs ` ( %s - 1 ) )' % RAT(A)
BND = lambda A: '( ( ( ( log ` 4 ) + E ) x. %s ) / ( log ` %s ) )' % (A, A)

# ---- ppiubepslem0: 1 < log 4
w = W('ppiubepslem0', 'The natural logarithm of 4 exceeds 1.')
e1 = w.s([], 'egt2lt3', '( 2 < _e /\\ _e < 3 )'); e2 = w.s([e1], 'simpri', '_e < 3')
r3 = w.s([], '3re', '3 e. RR'); r4 = w.s([], '4re', '4 e. RR'); ere = w.s([], 'ere', '_e e. RR')
l34 = w.s([], '3lt4', '3 < 4')
tri = w.s([ere, r3, r4], 'lttri', '( ( _e < 3 /\\ 3 < 4 ) -> _e < 4 )')
pr = w.s([e2, l34], 'pm3.2i', '( _e < 3 /\\ 3 < 4 )')
e4 = w.s([pr, tri], 'ax-mp', '_e < 4')
ep = w.s([], 'epr', '_e e. RR+'); p4 = w.s([], '4rp', '4 e. RR+')
b = w.s([ep, p4, w.inst('logltb')], 'mp2an', '( _e < 4 <-> ( log ` _e ) < ( log ` 4 ) )')
e5 = w.s([e4, b], 'mpbi', '( log ` _e ) < ( log ` 4 )')
le = w.s([], 'loge', '( log ` _e ) = 1')
w.qed([le, e5], 'eqbrtrri', '1 < ( log ` 4 )'); run(w)

# ---- ppiubepslem1: pointwise
A0 = '( ( A e. RR /\\ 2 <_ A /\\ E e. RR+ ) /\\ %s < E )' % ABS('A')
w = W('ppiubepslem1', 'Lemma for ppiubeps: if the PNT ratio is within eps of 1 at A >= 2, then pi ( A ) <_ ( log 4 + eps ) A / log A.')
a = w.s([], 'simpl1', '( %s -> A e. RR )' % A0); a2 = w.s([], 'simpl2', '( %s -> 2 <_ A )' % A0); e = w.s([], 'simpl3', '( %s -> E e. RR+ )' % A0); h = w.s([], 'simpr', '( %s -> %s < E )' % (A0, ABS('A')))
er = w.s([e], 'rpred', '( %s -> E e. RR )' % A0)
r1 = w.s([w.s([], '1re', '1 e. RR')], 'a1i', '( %s -> 1 e. RR )' % A0); r2 = w.s([w.s([], '2re', '2 e. RR')], 'a1i', '( %s -> 2 e. RR )' % A0)
l12 = w.s([w.s([], '1lt2', '1 < 2')], 'a1i', '( %s -> 1 < 2 )' % A0)
a1 = w.s([r1, r2, a, l12, a2], 'ltletrd', '( %s -> 1 < A )' % A0)
lg = w.s([a, a1], 'rplogcld', '( %s -> ( log ` A ) e. RR+ )' % A0); lgr = w.s([lg], 'rpred', '( %s -> ( log ` A ) e. RR )' % A0); lg0 = w.s([lg], 'rpgt0d', '( %s -> 0 < ( log ` A ) )' % A0)
z0 = w.s([w.s([], '0re', '0 e. RR')], 'a1i', '( %s -> 0 e. RR )' % A0); z1 = w.s([w.s([], '0lt1', '0 < 1')], 'a1i', '( %s -> 0 < 1 )' % A0)
a0 = w.s([z0, r1, a, z1, a1], 'lttrd', '( %s -> 0 < A )' % A0); ap = w.s([a, a0], 'elrpd', '( %s -> A e. RR+ )' % A0)
q = w.s([ap, lg], 'rpdivcld', '( %s -> ( A / ( log ` A ) ) e. RR+ )' % A0); qr = w.s([q], 'rpred', '( %s -> ( A / ( log ` A ) ) e. RR )' % A0); q0 = w.s([q], 'rpgt0d', '( %s -> 0 < ( A / ( log ` A ) ) )' % A0)
pp = w.s([a, w.inst('ppicl')], 'syl', '( %s -> ( ppi ` A ) e. NN0 )' % A0); ppr = w.s([pp], 'nn0red', '( %s -> ( ppi ` A ) e. RR )' % A0)
rat = w.s([ppr, q], 'rerpdivcld', '( %s -> %s e. RR )' % (A0, RAT('A'))); rat1 = w.s([rat, r1], 'resubcld', '( %s -> ( %s - 1 ) e. RR )' % (A0, RAT('A')))
ab = w.s([rat1, er, w.inst('abslt')], 'syl2anc', '( %s -> ( %s < E <-> ( -u E < ( %s - 1 ) /\\ ( %s - 1 ) < E ) ) )' % (A0, ABS('A'), RAT('A'), RAT('A')))
ab2 = w.s([h, ab], 'mpbid', '( %s -> ( -u E < ( %s - 1 ) /\\ ( %s - 1 ) < E ) )' % (A0, RAT('A'), RAT('A'))); ab3 = w.s([ab2], 'simprd', '( %s -> ( %s - 1 ) < E )' % (A0, RAT('A')))
ls = w.s([rat, r1, er, w.inst('ltsubadd')], 'syl3anc', '( %s -> ( ( %s - 1 ) < E <-> %s < ( E + 1 ) ) )' % (A0, RAT('A'), RAT('A')))
ab4 = w.s([ab3, ls], 'mpbid', '( %s -> %s < ( E + 1 ) )' % (A0, RAT('A')))
ec = w.s([er], 'recnd', '( %s -> E e. CC )' % A0); c1 = w.s([], '1cnd', '( %s -> 1 e. CC )' % A0)
ac = w.s([ec, c1], 'addcomd', '( %s -> ( E + 1 ) = ( 1 + E ) )' % A0)
ab5 = w.s([ab4, ac], 'breqtrd', '( %s -> %s < ( 1 + E ) )' % (A0, RAT('A')))
e1 = w.s([r1, er], 'readdcld', '( %s -> ( 1 + E ) e. RR )' % A0)
qpos = w.s([qr, q0], 'jca', '( %s -> ( ( A / ( log ` A ) ) e. RR /\\ 0 < ( A / ( log ` A ) ) ) )' % A0)
b2 = w.s([ppr, e1, qpos, w.inst('ltdivmul')], 'syl3anc', '( %s -> ( %s < ( 1 + E ) <-> ( ppi ` A ) < ( ( A / ( log ` A ) ) x. ( 1 + E ) ) ) )' % (A0, RAT('A')))
ab6 = w.s([ab5, b2], 'mpbid', '( %s -> ( ppi ` A ) < ( ( A / ( log ` A ) ) x. ( 1 + E ) ) )' % A0)
qc = w.s([qr], 'recnd', '( %s -> ( A / ( log ` A ) ) e. CC )' % A0); e1c = w.s([e1], 'recnd', '( %s -> ( 1 + E ) e. CC )' % A0)
cm = w.s([qc, e1c], 'mulcomd', '( %s -> ( ( A / ( log ` A ) ) x. ( 1 + E ) ) = ( ( 1 + E ) x. ( A / ( log ` A ) ) ) )' % A0)
acn = w.s([a], 'recnd', '( %s -> A e. CC )' % A0); lgc = w.s([lg], 'rpcnd', '( %s -> ( log ` A ) e. CC )' % A0); lgn0 = w.s([lg], 'rpne0d', '( %s -> ( log ` A ) =/= 0 )' % A0)
da = w.s([e1c, acn, lgc, lgn0], 'divassd', '( %s -> ( ( ( 1 + E ) x. A ) / ( log ` A ) ) = ( ( 1 + E ) x. ( A / ( log ` A ) ) ) )' % A0)
cm2 = w.s([cm, da], 'eqtr4d', '( %s -> ( ( A / ( log ` A ) ) x. ( 1 + E ) ) = ( ( ( 1 + E ) x. A ) / ( log ` A ) ) )' % A0)
ab7 = w.s([ab6, cm2], 'breqtrd', '( %s -> ( ppi ` A ) < ( ( ( 1 + E ) x. A ) / ( log ` A ) ) )' % A0)
e1a = w.s([e1, a], 'remulcld', '( %s -> ( ( 1 + E ) x. A ) e. RR )' % A0); e1al = w.s([e1a, lg], 'rerpdivcld', '( %s -> ( ( ( 1 + E ) x. A ) / ( log ` A ) ) e. RR )' % A0)
ab8 = w.s([ppr, e1al, ab7], 'ltled', '( %s -> ( ppi ` A ) <_ ( ( ( 1 + E ) x. A ) / ( log ` A ) ) )' % A0)
# ( 1 + E ) A / log A <_ ( log 4 + E ) A / log A
l4 = w.s([], 'ppiubepslem0', '1 < ( log ` 4 )'); l4r = w.s([w.s([], '4rp', '4 e. RR+'), w.inst('relogcl')], 'ax-mp', '( log ` 4 ) e. RR')
l4d = w.s([l4r], 'a1i', '( %s -> ( log ` 4 ) e. RR )' % A0); l4le = w.s([r1, l4d, w.s([l4], 'a1i', '( %s -> 1 < ( log ` 4 ) )' % A0)], 'ltled', '( %s -> 1 <_ ( log ` 4 ) )' % A0)
b3 = w.s([r1, l4d, er, w.inst('leadd1')], 'syl3anc', '( %s -> ( 1 <_ ( log ` 4 ) <-> ( 1 + E ) <_ ( ( log ` 4 ) + E ) ) )' % A0)
l4e = w.s([l4le, b3], 'mpbid', '( %s -> ( 1 + E ) <_ ( ( log ` 4 ) + E ) )' % A0)
l4er = w.s([l4d, er], 'readdcld', '( %s -> ( ( log ` 4 ) + E ) e. RR )' % A0)
a0le = w.s([a, a0], 'ltled' if False else 'ltled', '( %s -> 0 <_ A )' % A0) if False else w.s([z0, a, a0], 'ltled', '( %s -> 0 <_ A )' % A0)
apos = w.s([a, a0le], 'jca', '( %s -> ( A e. RR /\\ 0 <_ A ) )' % A0)
m1 = w.s([e1, l4er, apos], '3jca', '( %s -> ( ( 1 + E ) e. RR /\\ ( ( log ` 4 ) + E ) e. RR /\\ ( A e. RR /\\ 0 <_ A ) ) )' % A0)
m2 = w.s([m1, l4e, w.inst('lemul1a')], 'syl2anc', '( %s -> ( ( 1 + E ) x. A ) <_ ( ( ( log ` 4 ) + E ) x. A ) )' % A0)
l4ea = w.s([l4er, a], 'remulcld', '( %s -> ( ( ( log ` 4 ) + E ) x. A ) e. RR )' % A0)
lgpos = w.s([lgr, lg0], 'jca', '( %s -> ( ( log ` A ) e. RR /\\ 0 < ( log ` A ) ) )' % A0)
b4 = w.s([e1a, l4ea, lgpos, w.inst('lediv1')], 'syl3anc', '( %s -> ( ( ( 1 + E ) x. A ) <_ ( ( ( log ` 4 ) + E ) x. A ) <-> ( ( ( 1 + E ) x. A ) / ( log ` A ) ) <_ %s ) )' % (A0, BND('A')))
m3 = w.s([m2, b4], 'mpbid', '( %s -> ( ( ( 1 + E ) x. A ) / ( log ` A ) ) <_ %s )' % (A0, BND('A')))
bndr = w.s([l4ea, lg], 'rerpdivcld', '( %s -> %s e. RR )' % (A0, BND('A')))
w.qed([ppr, e1al, bndr, ab8, m3], 'letrd', '( %s -> ( ppi ` A ) <_ %s )' % (A0, BND('A'))); run(w)

# ---- ppiubepslem2: the PNT unpacked at radius E
w = W('ppiubepslem2', 'Lemma for ppiubeps: the prime number theorem unpacked at radius eps.')
X = 'x e. ( 1 (,) +oo )'
x1 = w.s([], 'elioore', '( %s -> x e. RR )' % X); x2 = w.s([], 'eliooord', '( %s -> ( 1 < x /\\ x < +oo ) )' % X); x3 = w.s([x2], 'simpld', '( %s -> 1 < x )' % X)
x4 = w.s([x1, x3], 'rplogcld', '( %s -> ( log ` x ) e. RR+ )' % X)
z0 = w.s([w.s([], '0re', '0 e. RR')], 'a1i', '( %s -> 0 e. RR )' % X); r1 = w.s([w.s([], '1re', '1 e. RR')], 'a1i', '( %s -> 1 e. RR )' % X); z1 = w.s([w.s([], '0lt1', '0 < 1')], 'a1i', '( %s -> 0 < 1 )' % X)
x5 = w.s([z0, r1, x1, z1, x3], 'lttrd', '( %s -> 0 < x )' % X); x6 = w.s([x1, x5], 'elrpd', '( %s -> x e. RR+ )' % X)
x7 = w.s([x6, x4], 'rpdivcld', '( %s -> ( x / ( log ` x ) ) e. RR+ )' % X)
x8 = w.s([x1, w.inst('ppicl')], 'syl', '( %s -> ( ppi ` x ) e. NN0 )' % X); x9 = w.s([x8], 'nn0red', '( %s -> ( ppi ` x ) e. RR )' % X)
x10 = w.s([x9, x7], 'rerpdivcld', '( %s -> %s e. RR )' % (X, RAT('x')))
x11 = w.s([x10], 'rgen', 'A. x e. ( 1 (,) +oo ) %s e. RR' % RAT('x')); x12 = w.s([x11], 'a1i', '( E e. RR+ -> A. x e. ( 1 (,) +oo ) %s e. RR )' % RAT('x'))
e = w.s([], 'id', '( E e. RR+ -> E e. RR+ )')
p = w.s([], 'pnt', '( x e. ( 1 (,) +oo ) |-> %s ) ~~>r 1' % RAT('x')); pd = w.s([p], 'a1i', '( E e. RR+ -> ( x e. ( 1 (,) +oo ) |-> %s ) ~~>r 1 )' % RAT('x'))
w.qed([x12, e, pd], 'rlimi', '( E e. RR+ -> E. y e. RR A. x e. ( 1 (,) +oo ) ( y <_ x -> %s < E ) )' % ABS('x')); run(w)

# ---- ppiubepslem3: threshold
ALL = 'A. x e. ( 1 (,) +oo ) ( y <_ x -> %s < E )' % ABS('x')
T = '( ( ( |_ ` ( abs ` y ) ) + 1 ) + 1 )'
A3 = '( ( E e. RR+ /\\ y e. RR /\\ %s ) /\\ z e. ( ZZ>= ` %s ) )' % (ALL, T)
w = W('ppiubepslem3', 'Lemma for ppiubeps: from a PNT threshold y, every integer z >= floor ( | y | ) + 2 satisfies pi ( z ) <_ ( log 4 + eps ) z / log z.')
e = w.s([], 'simpl1', '( %s -> E e. RR+ )' % A3); y = w.s([], 'simpl2', '( %s -> y e. RR )' % A3); al = w.s([], 'simpl3', '( %s -> %s )' % (A3, ALL)); z = w.s([], 'simpr', '( %s -> z e. ( ZZ>= ` %s ) )' % (A3, T))
yc = w.s([y], 'recnd', '( %s -> y e. CC )' % A3); ay = w.s([yc], 'abscld', '( %s -> ( abs ` y ) e. RR )' % A3); ay0 = w.s([yc], 'absge0d', '( %s -> 0 <_ ( abs ` y ) )' % A3)
f = w.s([ay, ay0, w.inst('flge0nn0')], 'syl2anc', '( %s -> ( |_ ` ( abs ` y ) ) e. NN0 )' % A3)
f1 = w.s([f, w.inst('nn0p1nn')], 'syl', '( %s -> ( ( |_ ` ( abs ` y ) ) + 1 ) e. NN )' % A3); f2 = w.s([f1, w.inst('peano2nn')], 'syl', '( %s -> %s e. NN )' % (A3, T))
zn = w.s([f2, z, w.inst('eluznn')], 'syl2anc', '( %s -> z e. NN )' % A3); zr = w.s([zn], 'nnred', '( %s -> z e. RR )' % A3)
tz = w.s([z, w.inst('eluzle')], 'syl', '( %s -> %s <_ z )' % (A3, T)); tr = w.s([f2], 'nnred', '( %s -> %s e. RR )' % (A3, T)); f1r = w.s([f1], 'nnred', '( %s -> ( ( |_ ` ( abs ` y ) ) + 1 ) e. RR )' % A3)
g1 = w.s([f1, w.inst('nnge1')], 'syl', '( %s -> 1 <_ ( ( |_ ` ( abs ` y ) ) + 1 ) )' % A3)
r1 = w.s([w.s([], '1re', '1 e. RR')], 'a1i', '( %s -> 1 e. RR )' % A3)
g2 = w.s([r1, f1r, r1, g1], 'leadd1dd', '( %s -> ( 1 + 1 ) <_ %s )' % (A3, T))
g3 = w.s([w.s([], '1p1e2', '( 1 + 1 ) = 2')], 'a1i', '( %s -> ( 1 + 1 ) = 2 )' % A3); g4 = w.s([g3, g2], 'eqbrtrrd', '( %s -> 2 <_ %s )' % (A3, T))
r2 = w.s([w.s([], '2re', '2 e. RR')], 'a1i', '( %s -> 2 e. RR )' % A3)
g5 = w.s([r2, tr, zr, g4, tz], 'letrd', '( %s -> 2 <_ z )' % A3)
l12 = w.s([w.s([], '1lt2', '1 < 2')], 'a1i', '( %s -> 1 < 2 )' % A3); g6 = w.s([r1, r2, zr, l12, g5], 'ltletrd', '( %s -> 1 < z )' % A3)
g7 = w.s([zr, g6], 'jca', '( %s -> ( z e. RR /\\ 1 < z ) )' % A3)
io = w.s([w.s([], '1xr', '1 e. RR*'), w.inst('elioopnf')], 'ax-mp', '( z e. ( 1 (,) +oo ) <-> ( z e. RR /\\ 1 < z ) )')
g8 = w.s([g7, io], 'sylibr', '( %s -> z e. ( 1 (,) +oo ) )' % A3)
lb = w.s([y], 'leabsd', '( %s -> y <_ ( abs ` y ) )' % A3); fl = w.s([ay, w.inst('flltp1')], 'syl', '( %s -> ( abs ` y ) < ( ( |_ ` ( abs ` y ) ) + 1 ) )' % A3)
p1 = w.s([f1r], 'ltp1d', '( %s -> ( ( |_ ` ( abs ` y ) ) + 1 ) < %s )' % (A3, T))
y1 = w.s([y, ay, f1r, lb, fl], 'lelttrd', '( %s -> y < ( ( |_ ` ( abs ` y ) ) + 1 ) )' % A3); y2 = w.s([y, f1r, tr, y1, p1], 'lttrd', '( %s -> y < %s )' % (A3, T))
y3 = w.s([y, tr, zr, y2, tz], 'ltletrd', '( %s -> y < z )' % A3); y4 = w.s([y, zr, y3], 'ltled', '( %s -> y <_ z )' % A3)
s1 = w.s([], 'breq2', '( x = z -> ( y <_ x <-> y <_ z ) )')
s2 = w.s([], 'fveq2', '( x = z -> ( ppi ` x ) = ( ppi ` z ) )'); s3 = w.s([], 'id', '( x = z -> x = z )'); s4 = w.s([], 'fveq2', '( x = z -> ( log ` x ) = ( log ` z ) )')
s5 = w.s([s3, s4], 'oveq12d', '( x = z -> ( x / ( log ` x ) ) = ( z / ( log ` z ) ) )'); s6 = w.s([s2, s5], 'oveq12d', '( x = z -> %s = %s )' % (RAT('x'), RAT('z')))
s7 = w.s([s6], 'oveq1d', '( x = z -> ( %s - 1 ) = ( %s - 1 ) )' % (RAT('x'), RAT('z'))); s8 = w.s([s7], 'fveq2d', '( x = z -> %s = %s )' % (ABS('x'), ABS('z')))
s9 = w.s([s8], 'breq1d', '( x = z -> ( %s < E <-> %s < E ) )' % (ABS('x'), ABS('z')))
s10 = w.s([s1, s9], 'imbi12d', '( x = z -> ( ( y <_ x -> %s < E ) <-> ( y <_ z -> %s < E ) ) )' % (ABS('x'), ABS('z')))
i1 = w.s([s10, al, g8], 'rspcdva', '( %s -> ( y <_ z -> %s < E ) )' % (A3, ABS('z')))
i2 = w.s([y4, i1], 'mpd', '( %s -> %s < E )' % (A3, ABS('z')))
i3 = w.s([zr, g5, e], '3jca', '( %s -> ( z e. RR /\\ 2 <_ z /\\ E e. RR+ ) )' % A3)
i4 = w.s([i3, i2, w.inst('ppiubepslem1')], 'syl2anc', '( %s -> ( ppi ` z ) <_ %s )' % (A3, BND('z')))
w.qed([i4], 'ralrimiva', '( ( E e. RR+ /\\ y e. RR /\\ %s ) -> A. z e. ( ZZ>= ` %s ) ( ppi ` z ) <_ %s )' % (ALL, T, BND('z'))); run(w)

# ---- ppiubeps
w = W('ppiubeps', "Chebyshev's upper bound with an explicit constant: for every eps > 0 and all sufficiently large integers z, pi ( z ) <_ ( log 4 + eps ) z / log z (Lean: eventually_primePi_le, via pnt).")
A4 = '( E e. RR+ /\\ ( y e. RR /\\ %s ) )' % ALL
l2 = w.s([], 'ppiubepslem2', '( E e. RR+ -> E. y e. RR %s )' % ALL)
e = w.s([], 'simpl', '( %s -> E e. RR+ )' % A4); y = w.s([], 'simprl', '( %s -> y e. RR )' % A4); al = w.s([], 'simprr', '( %s -> %s )' % (A4, ALL))
yc = w.s([y], 'recnd', '( %s -> y e. CC )' % A4); ay = w.s([yc], 'abscld', '( %s -> ( abs ` y ) e. RR )' % A4); ay0 = w.s([yc], 'absge0d', '( %s -> 0 <_ ( abs ` y ) )' % A4)
f = w.s([ay, ay0, w.inst('flge0nn0')], 'syl2anc', '( %s -> ( |_ ` ( abs ` y ) ) e. NN0 )' % A4)
f1 = w.s([f, w.inst('nn0p1nn')], 'syl', '( %s -> ( ( |_ ` ( abs ` y ) ) + 1 ) e. NN )' % A4); f2 = w.s([f1, w.inst('peano2nn')], 'syl', '( %s -> %s e. NN )' % (A4, T))
l3 = w.s([e, y, al, w.inst('ppiubepslem3')], 'syl3anc', '( %s -> A. z e. ( ZZ>= ` %s ) ( ppi ` z ) <_ %s )' % (A4, T, BND('z')))
c1 = w.s([], 'fveq2', '( m = %s -> ( ZZ>= ` m ) = ( ZZ>= ` %s ) )' % (T, T))
c2 = w.s([c1], 'raleqdv', '( m = %s -> ( A. z e. ( ZZ>= ` m ) ( ppi ` z ) <_ %s <-> A. z e. ( ZZ>= ` %s ) ( ppi ` z ) <_ %s ) )' % (T, BND('z'), T, BND('z')))
c3 = w.s([c2], 'rspcev', '( ( %s e. NN /\\ A. z e. ( ZZ>= ` %s ) ( ppi ` z ) <_ %s ) -> E. m e. NN A. z e. ( ZZ>= ` m ) ( ppi ` z ) <_ %s )' % (T, T, BND('z'), BND('z')))
c4 = w.s([f2, l3, c3], 'syl2anc', '( %s -> E. m e. NN A. z e. ( ZZ>= ` m ) ( ppi ` z ) <_ %s )' % (A4, BND('z')))
c5 = w.s([c4], 'rexlimdvaa', '( E e. RR+ -> ( E. y e. RR %s -> E. m e. NN A. z e. ( ZZ>= ` m ) ( ppi ` z ) <_ %s ) )' % (ALL, BND('z')))
w.qed([l2, c5], 'mpd', '( E e. RR+ -> E. m e. NN A. z e. ( ZZ>= ` m ) ( ppi ` z ) <_ %s )' % BND('z')); run(w)
